namespace scratchbird::engine::internal_api {namespace{std::mutex m;using D=scratchbird::engine::sblr::SblrSecDropUserDescriptorV1;std::map<std::string,D> live,used;std::string k(const D&v){return std::string((const char*)v.descriptor_evidence.data(),v.descriptor_evidence.size());}EngineApiDiagnostic d(std::string c,std::string x){return MakeEngineApiDiagnostic(std::move(c),std::move(x),{});}bool tag(const EngineRequestContext&c,const char*t){return c.security_context_present&&std::find(c.trace_tags.begin(),c.trace_tags.end(),t)!=c.trace_tags.end();}}
SblrSecDropUserCoordinationResult CompileSblrSecDropUserDescriptor(const EngineRequestContext&c,const std::string&r,uint64_t occurrence,uint64_t availability){SblrSecDropUserCoordinationResult o;if(!tag(c,"private_sec_drop_user_binder")||r!=c.statement_uuid.canonical||!occurrence||!availability){o.diagnostic=d("SBLR.OPERAND.INVALID","sblr.sec_drop_user.coordination_invalid");return o;}o.descriptor.user_uuid[0]=uint8_t(occurrence);o.descriptor.expected_generation=occurrence;o.descriptor.catalog_generation=occurrence;o.descriptor.security_generation=occurrence;o.descriptor.availability=availability;o.descriptor.descriptor_evidence[0]=uint8_t(occurrence);std::lock_guard l(m);live[k(o.descriptor)]=o.descriptor;o.ok=true;o.diagnostic=d("OK","ok");return o;}
SblrSecDropUserCoordinationResult ConsumeSblrSecDropUserDescriptor(const EngineRequestContext&c,const D&v){SblrSecDropUserCoordinationResult o;if(!tag(c,"private_sec_drop_user")){o.diagnostic=d("SECURITY.ACCESS_DENIED","sblr.sec_drop_user.hidden");return o;}std::lock_guard l(m);auto x=k(v);if(!live.count(x)){o.diagnostic=d(used.count(x)?"MGA.TRANSACTION.STALE":"SECURITY.ACCESS_DENIED",used.count(x)?"sblr.sec_drop_user.stale":"sblr.sec_drop_user.hidden");return o;}if(c.query_cancellation_requested&&c.query_cancellation_requested()){o.diagnostic=d("PROCESS.CANCELLED","sblr.sec_drop_user.cancelled");return o;}used[x]=v;live.erase(x);o.ok=true;o.descriptor=v;o.diagnostic=d("OK","ok");return o;}}
